// Accepts batch payloads from the new script as well as legacy single payloads
const raw = $input.first()?.json?.body || $input.first()?.json || {};

const routerId = raw.router_id || 'Unknown-Router';
const routerUptime = raw.uptime || null;
const recordedAt = new Date().toISOString();

const users = Array.isArray(raw.users) ? raw.users : [];
// Supports both 'sessions' (minified) and 'active_sessions' (legacy)
const activeSessions = Array.isArray(raw.sessions) ? raw.sessions : (Array.isArray(raw.active_sessions) ? raw.active_sessions : []);

// Build session lookup index
const activeMap = new Map();
for (const s of activeSessions) {
  const uKey = s.user || s.name;
  if (!uKey) continue;
  if (!activeMap.has(uKey)) {
    activeMap.set(uKey, []);
  }
  activeMap.get(uKey).push({
    ip_address: s.ip || s.address || null,
    mac_address: s.mac || s.mac_address || null,
    session_uptime: s.uptime || null,
    rx_bytes: Number(s.rx !== undefined ? s.rx : (s.bytes_in || 0)),
    tx_bytes: Number(s.tx !== undefined ? s.tx : (s.bytes_out || 0))
  });
}

const MB = 1024 * 1024;
const GB = 1024 * 1024 * 1024;

const processedBatch = users.map(u => {
  // Support minified keys (rx, tx, limit) and legacy keys (bytes_in, bytes_out, limit_bytes_total)
  const rxBytes = Number(u.rx !== undefined ? u.rx : (u.bytes_in || 0));
  const txBytes = Number(u.tx !== undefined ? u.tx : (u.bytes_out || 0));
  const totalUsedBytes = rxBytes + txBytes;
  const limitTotalBytes = Number(u.limit !== undefined ? u.limit : (u.limit_bytes_total || 0));
  const hasLimit = limitTotalBytes > 0;

  let remainingBytes = 0;
  let usedPercentage = 0;

  if (hasLimit) {
    remainingBytes = Math.max(0, limitTotalBytes - totalUsedBytes);
    usedPercentage = Number(Math.min(100, (totalUsedBytes / limitTotalBytes) * 100).toFixed(2));
  }

  const sessions = activeMap.get(u.name) || [];
  const primarySession = sessions[0] || null;

  return {
    router_id: routerId,
    user_name: u.name,
    profile: u.profile || null,
    comment: u.comment || null,
    is_active: sessions.length > 0,
    active_connections_count: sessions.length,
    ip_address: primarySession?.ip_address || null,
    mac_address: primarySession?.mac_address || null,
    session_uptime: primarySession?.session_uptime || null,

    // Counters
    bytes_in: rxBytes,
    bytes_out: txBytes,
    total_bytes: totalUsedBytes,
    limit_bytes_total: limitTotalBytes,
    remaining_bytes: remainingBytes,

    // Metrics (2 decimal precision)
    total_mb: Number((totalUsedBytes / MB).toFixed(2)),
    total_gb: Number((totalUsedBytes / GB).toFixed(2)),
    limit_gb: hasLimit ? Number((limitTotalBytes / GB).toFixed(2)) : null,
    remaining_gb: hasLimit ? Number((remainingBytes / GB).toFixed(2)) : null,
    used_percentage: usedPercentage,

    // Threshold classification
    alert_tier: usedPercentage >= 100 ? '100%' : (usedPercentage >= 80 ? '80%' : 'NORMAL'),
    recorded_at: recordedAt
  };
});

return processedBatch.map(item => ({ json: item }));

const item = $('Normalize & Calculate Quota').item.json;
const isExhausted = item.alert_tier === '100%';

const title = isExhausted 
  ? '🚨 <b>إنذار: نفاد كوتا مستخدم هوتسبوت بالكامل (100%)</b>'
  : '⚠️ <b>تنبيه: اقتراب نفاد كوتا مستخدم هوتسبوت (80%)</b>';

let msg = `${title}\n\n`;
msg += `👤 المستخدم: <b>${item.user_name}</b>\n`;
msg += `🏷️ البروفايل: <code>${item.profile || 'Default'}</code>\n`;
msg += `🖥️ الراوتر: <code>${item.router_id}</code>\n`;
msg += `📊 الاستهلاك: <b>${item.used_percentage}%</b> (${item.total_gb} GB / ${item.limit_gb} GB)\n`;
msg += `📉 المتبقي: <b>${item.remaining_gb} GB</b>\n`;
if (item.ip_address) {
  msg += `🌐 العنوان: <code>${item.ip_address}</code> (${item.mac_address})\n`;
}
if (item.comment) {
  msg += `📝 ملاحظة: <i>${item.comment}</i>\n`;
}
msg += `📅 التوقيت: <code>${new Date(item.recorded_at).toLocaleString('ar-EG', { timeZone: 'Africa/Cairo' })}</code>`;

return [{
  json: {
    ...item,
    telegram_alert: msg
  }
}];
